import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { exportCustomersWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { transaction } = await exportCustomersWorkflow(req.scope).run({
    input: {
      select: ["addresses.*", "orders.*"],
      filter: { id: "cus_123" },
      format: "json",
    },
  })

  res.send(result)
}

